def _qtwe_locale_override(versions: version.WebEngineVersions) -> Optional[str]:
    """Get a --lang override for QtWebEngine 5.15.3 on Linux when needed.

    This applies a guarded workaround for locale handling in QtWebEngine 5.15.3
    where certain BCP47 locales cause Chromium subprocess startup failures when
    a matching .pak is missing.
    """
    if not utils.is_linux:
        return None
    if versions.webengine != utils.VersionNumber(5, 15, 3):
        return None
    try:
        active = QLocale().bcp47Name().replace('_', '-')
    except Exception:
        return None

    def _norm(tag: str) -> str:
        parts = tag.split('-')
        if not parts:
            return tag
        lang = parts[0].lower()
        if len(parts) >= 2:
            region = parts[1].upper()
            return f"{lang}-{region}"
        return lang

    def _locales_dir() -> Optional[str]:
        trans = QLibraryInfo.location(QLibraryInfo.TranslationsPath)
        cand1 = os.path.join(trans, 'qtwebengine_locales')
        if os.path.isdir(cand1):
            return cand1
        data = QLibraryInfo.location(QLibraryInfo.DataPath)
        cand2 = os.path.join(data, 'resources', 'qtwebengine_locales')
        if os.path.isdir(cand2):
            return cand2
        return None

    def _exists(locale_dir: str, tag: str) -> bool:
        # Check common filename variants
        t1 = _norm(tag)
        t2 = t1.split('-')
        if len(t2) == 2:
            llcc_lower = f"{t2[0]}-{t2[1].lower()}"
        else:
            llcc_lower = t1
        for candidate in [t1, llcc_lower]:
            if os.path.exists(os.path.join(locale_dir, candidate + '.pak')):
                return True
        return False

    locale_dir = _locales_dir()
    if not locale_dir:
        return None

    normalized = _norm(active)
    if _exists(locale_dir, normalized):
        return None

    # Compute sensible fallbacks mirroring Chromium's own mappings
    parts = normalized.split('-')
    lang = parts[0]
    region = parts[1] if len(parts) >= 2 else None

    fallback = None
    if lang == 'en':
        fallback = 'en-GB'
    elif lang == 'es':
        fallback = 'es-419'  # Spanish (Latin America)
    elif lang == 'pt':
        if region is None:
            fallback = 'pt-BR'
        else:
            fallback = 'pt-PT'
    elif lang == 'zh':
        # Map known regions to commonly available locales
        if region in {'CN', 'SG'}:
            fallback = 'zh-CN'
        elif region in {'TW', 'HK', 'MO'}:
            fallback = 'zh-TW'
        else:
            fallback = 'zh-CN'

    # If we computed a fallback and it exists, use it
    if fallback and _exists(locale_dir, fallback):
        return '--lang=' + fallback

    # Otherwise, fall back to language-only if available
    if _exists(locale_dir, lang):
        return '--lang=' + lang

    # As a last resort, if we computed a fallback, use it regardless
    if fallback:
        return '--lang=' + fallback

    # No override
    return None

