    # Determine active BCP47 locale
    active = None
    try:
        from PyQt5.QtCore import QLocale  # type: ignore
        active = QLocale().bcp47Name().replace('_', '-')
    except Exception:
        lang = os.environ.get('LANG') or os.environ.get('LC_ALL') or ''
        if '.' in lang:
            lang = lang.split('.', 1)[0]
        active = lang.replace('_', '-') if lang else None
    if not active:
        return None

    def _norm(tag: str) -> str:
        parts = tag.split('-')
        if not parts:
            return tag
        lang = parts[0].lower()
        if len(parts) >= 2:
            region = parts[1].upper()
            return f"{lang}-{region}"
        return lang

    def _locales_dir() -> Optional[str]:
        # Prefer Qt-provided paths
        try:
            from PyQt5.QtCore import QLibraryInfo  # type: ignore
            trans = QLibraryInfo.location(QLibraryInfo.TranslationsPath)
            cand1 = os.path.join(trans, 'qtwebengine_locales')
            if os.path.isdir(cand1):
                return cand1
            data = QLibraryInfo.location(QLibraryInfo.DataPath)
            cand2 = os.path.join(data, 'resources', 'qtwebengine_locales')
            if os.path.isdir(cand2):
                return cand2
        except Exception:
            pass
        # Fallback to some common locations / env overrides
        env = os.environ.get('QTWEBENGINE_LOCALES_PATH')
        if env and os.path.isdir(env):
            return env
        for path in [
            '/usr/share/qt/translations/qtwebengine_locales',
            '/usr/share/qt5/translations/qtwebengine_locales',
            '/usr/lib/qt5/translations/qtwebengine_locales',
        ]:
            if os.path.isdir(path):
                return path
        return None

    def _exists(locale_dir: str, tag: str) -> bool:
        t1 = _norm(tag)
        t2 = t1.split('-')
        if len(t2) == 2:
            llcc_lower = f"{t2[0]}-{t2[1].lower()}"
        else:
            llcc_lower = t1
        for candidate in [t1, llcc_lower]:
            if os.path.exists(os.path.join(locale_dir, candidate + '.pak')):
                return True
        return False

    locale_dir = _locales_dir()
    if not locale_dir:
        return None

    normalized = _norm(active)
    if _exists(locale_dir, normalized):
        return None

    parts = normalized.split('-')
    lang = parts[0]
    region = parts[1] if len(parts) >= 2 else None

    fallback = None
    if lang == 'en':
        fallback = 'en-GB'
    elif lang == 'es':
        fallback = 'es-419'
    elif lang == 'pt':
        fallback = 'pt-BR' if region is None else 'pt-PT'
    elif lang == 'zh':
        if region in {'CN', 'SG'}:
            fallback = 'zh-CN'
        elif region in {'TW', 'HK', 'MO'}:
            fallback = 'zh-TW'
        else:
            fallback = 'zh-CN'

